<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';$merchant=require_login();$pageTitle='API Keys';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$key='tg_'.bin2hex(random_bytes(30));$pdo->prepare('UPDATE merchants SET api_key=? WHERE id=?')->execute([$key,$merchant['id']]);$notice='API key rotated. Update your integrations now; the old key is no longer valid.';}$q=$pdo->prepare('SELECT api_key,api_key_last_used_at FROM merchants WHERE id=?');$q->execute([$merchant['id']]);$keyRow=$q->fetch();$key=$keyRow['api_key'];$lastUsed=$keyRow['api_key_last_used_at'] ?? null;$days=[];$activityAvailable=true;
try {
    $counts=$pdo->prepare('SELECT activity_date d, request_count n FROM api_request_activity WHERE merchant_id=? AND activity_date>=?');
    $counts->execute([$merchant['id'],date('Y-m-d',strtotime('-6 days'))]);
    foreach($counts->fetchAll() as $r) $days[$r['d']]=(int)$r['n'];
} catch (Throwable $e) { $activityAvailable=false; error_log('API activity: '.$e->getMessage()); }
$max=max(1, ...(array_values($days) ?: [1]));
require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title-row" style="margin-bottom:24px"><div><h1>API keys</h1><p>Authenticate server-to-server requests to the TG Gateways API.</p></div></div><?php if(!empty($notice)):?><div class="note panel"><?=h($notice)?></div><?php endif?><div class="dashboard-bottom-grid"><div class="card"><div class="card-title"><h3>Default API key</h3><span class="badge badge-success">Active</span></div><p class="key-usage"><?php if($lastUsed):?>Last used <?=h(tg_time_ago((string)$lastUsed))?>.<?php else:?>This key has not been used yet &mdash; it works as soon as your first API call arrives.<?php endif?></p><div class="field"><label>SECRET KEY · KEEP PRIVATE</label><div style="display:flex;gap:7px"><input class="form-input" id="api-key" value="<?=h($key)?>" type="password" readonly><button class="btn btn-secondary" data-toggle="#api-key">Reveal</button><button class="btn btn-secondary" onclick="navigator.clipboard.writeText(document.getElementById('api-key').value)">Copy</button></div></div><div class="callout callout-info" style="margin-top:15px">Never include your secret API key in a browser app, public repository, or client-side JavaScript. Rotate it immediately if exposed.</div><form method="post" style="margin-top:17px" onsubmit="return confirm('Rotate this key? Existing integrations will stop working.');"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><button class="btn btn-secondary">Roll API key</button></form></div><div class="card"><div class="card-title"><h3>API request activity</h3><span class="form-hint">Last 7 days · server time</span></div>
<?php if (!$activityAvailable): ?><p class="api-activity-hint">Activity tracking is unavailable. Check database migrations.</p><?php else: ?>
<div class="api-activity-chart" aria-label="Authenticated API requests over the last seven days">
<?php for($i=6;$i>=0;$i--): $d=date('Y-m-d',strtotime("-$i days")); $count=$days[$d]??0; ?>
  <div class="api-activity-day" title="<?=h($d)?>: <?=$count?> requests"><span class="api-activity-value"><?=$count?></span><div class="api-activity-track"><div class="api-activity-bar" style="height:<?=($count ? max(4, (int)round($count/$max*100)) : 0)?>%"></div></div><span class="api-activity-label"><?=date('D',strtotime($d))?></span></div>
<?php endfor ?>
</div><p class="api-activity-hint">Authenticated API-key requests, including unsuccessful endpoint responses after authentication. Tracking starts with this update; earlier activity is not available.</p>
<?php endif ?></div></div><?php require __DIR__.'/includes/dashboard-footer.php';?>